// Týždenná syntéza: spája nápady medzi sebou a s mojím profilom.
const input = $input.first().json;
const items = (input.items || []).map(i => ({
  id: i.id, title: i.title, category: i.category, summary: i.summary, keyPoints: i.keyPoints,
  frameworks: i.frameworks, businessIdeas: i.businessIdeas, relevance: i.relevanceScore,
  tags: i.tags, starred: i.starred, note: i.userNote,
}));
const str = { type: 'string' };
const arr = x => ({ type: 'array', items: x });
const obj = p => ({ type: 'object', additionalProperties: false, required: Object.keys(p), properties: p });
const schema = obj({
  title: str, summary: str,
  themes: arr(obj({ name: str, insight: str, captureIds: arr(str) })),
  topActions: arr(str), businessBets: arr(str), questions: arr(str),
});
const instructions = [
  'Si VERA, moja kurátorka nápadov (Idea Vault). Dostaneš všetko, čo som za posledný týždeň uložil do trezora nápadov, a môj profil.',
  'Píš po slovensky, konkrétne, bez všeobecných fráz.',
  '- title: pomenuj hlavný motív týždňa.',
  '- summary: 3–5 viet – čo ma tento týždeň ťahalo, aký vzorec vidíš a čo to znamená pre moje projekty.',
  '- themes: 2–5 tém, ktoré spájajú viac záznamov. insight = čo z ich prepojenia vyplýva (nie zoznam). captureIds iba zo vstupu.',
  '- topActions: max 3 najhodnotnejšie kroky na budúci týždeň, naviazané na moje projekty.',
  '- businessBets: max 3 biznis nápady, ktoré vznikajú KOMBINÁCIOU záznamov a mojich projektov.',
  '- questions: max 3 otázky, ktoré by som si mal položiť.',
  'Záznamy označené ako obľúbené (starred) a s poznámkou ber ako silnejší signál.',
  '',
  'MÔJ PROFIL:',
  input.promptContext || '',
].join('\n');
return [{ json: {
  periodStart: input.periodStart, periodEnd: input.periodEnd, captureCount: input.captureCount,
  requestBody: {
    model: 'gpt-5-mini', instructions,
    input: [{ role: 'user', content: [{ type: 'input_text', text: JSON.stringify(items) }] }],
    reasoning: { effort: 'medium' }, max_output_tokens: 8000,
    text: { format: { type: 'json_schema', name: 'idea_digest', strict: true, schema } },
  },
} }];

const prepared = $('Priprav týždennú syntézu').first().json;
const j = $input.first().json || {};
let text = j.output_text || '';
if (!text && Array.isArray(j.output)) text = j.output.flatMap(x => x.content || []).filter(x => x.type === 'output_text').map(x => x.text || '').join('');
let digest;
try { digest = JSON.parse(text); } catch { throw new Error('Digest: AI nevrátila platný JSON' + (j.error ? ' – ' + (j.error.message || j.error) : '')); }
return [{ json: { payload: { periodStart: prepared.periodStart, periodEnd: prepared.periodEnd, captureCount: prepared.captureCount, digest } } }];

const d = $('Rozparsuj syntézu').first().json.payload.digest;
const saved = $input.first().json || {};
const lines = ['🗂 VERA · týždenný prehľad nápadov', '', d.title, d.summary];
if (d.themes?.length) lines.push('', 'Témy:', ...d.themes.map(t => '• ' + t.name + ' – ' + t.insight));
if (d.topActions?.length) lines.push('', 'Na budúci týždeň:', ...d.topActions.map((a, i) => (i + 1) + '. ' + a));
if (d.businessBets?.length) lines.push('', '🚀 Biznis stávky:', ...d.businessBets.map(b => '• ' + b));
if (d.questions?.length) lines.push('', '❓ ' + d.questions.join('\n❓ '));
if (saved.ok !== true) lines.push('', '⚠️ Digest sa nepodarilo uložiť do dashboardu.');
return [{ json: { text: lines.join('\n').slice(0, 3900) } }];
